import time, numpy as np
np.random.seed(2)
eig_ll = np.linalg._umath_linalg.eig

def med(fn, n=400):
    dts=[]
    for _ in range(n):
        t0=time.perf_counter(); fn(); t1=time.perf_counter()
        dts.append(t1-t0)
    return float(np.median(dts))*1e6

for size in [2,4,6,8,10]:
    A = np.random.normal(size=(size,size)).astype(np.float64)
    w, V = eig_ll(A)
    def t_call():   return eig_ll(A)
    def t_wabs():   return np.abs(w)
    def t_argmax(): return int(np.argmax(np.abs(w)))
    def t_full():
        w2,V2 = eig_ll(A); i=int(np.argmax(np.abs(w2))); return w2[i], V2[:,i]
    def t_full2():
        w2,V2 = eig_ll(A); i=int(np.argmax(w2.real**2+w2.imag**2)); return w2[i], V2[:,i]
    print(f"size {size:2d}: call {med(t_call):6.1f} | +abs {med(t_wabs):5.2f} | +argmax {med(t_argmax):5.2f} | full {med(t_full):6.1f} | full2 {med(t_full2):6.1f}")
EOF
